import { COASTLINE } from './coastline-data.js';
import { wrapLongitude } from './sun.js';

/**
 * Whether a point is far from the sea, to keep sea-only information such as
 * tides from being shown for the middle of an island.
 *
 * The land polygons (coastline-data.ts, generated by scripts/build-coastline.mjs)
 * cover Australia, New Zealand and the south-west Pacific. A point that is not
 * inside one of them - open water, a harbour, an area the data does not cover -
 * is never reported as inland, so callers fail open and keep showing the result.
 */

/** A point on land further than this from the sea is inland. */
export const INLAND_KM = 10;

const KM_PER_DEGREE_LATITUDE = 110.574;
const KM_PER_DEGREE_LONGITUDE_AT_EQUATOR = 111.32;

type LandPolygon = {
    west: number;
    east: number;
    south: number;
    north: number;
    /** Outline first, then holes - each a flat longitude, latitude, ... list */
    rings: ArrayLike<number>[];
};

let polygons: LandPolygon[] | undefined;

function load(): LandPolygon[] {
    if (polygons) return polygons;

    polygons = COASTLINE.map((rings) => {
        const outline = rings[0];
        let west = Infinity;
        let east = -Infinity;
        let south = Infinity;
        let north = -Infinity;

        for (let i = 0; i < outline.length; i += 2) {
            west = Math.min(west, outline[i]);
            east = Math.max(east, outline[i]);
            south = Math.min(south, outline[i + 1]);
            north = Math.max(north, outline[i + 1]);
        }

        return { west, east, south, north, rings: rings.map(ring => Float64Array.from(ring)) };
    });

    return polygons;
}

/** Even-odd ray casting test of a point against one closed ring */
function inRing(x: number, y: number, ring: ArrayLike<number>): boolean {
    let inside = false;

    for (let i = 0, j = ring.length - 2; i < ring.length; j = i, i += 2) {
        const xi = ring[i];
        const yi = ring[i + 1];
        const xj = ring[j];
        const yj = ring[j + 1];

        if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
    }

    return inside;
}

function inPolygon(x: number, y: number, polygon: LandPolygon): boolean {
    if (!inRing(x, y, polygon.rings[0])) return false;

    for (let i = 1; i < polygon.rings.length; i++) {
        if (inRing(x, y, polygon.rings[i])) return false;
    }

    return true;
}

/**
 * Distance in km from a point to the nearest edge of the polygon, measured on a plane
 * centred on the point - accurate to well under a percent over the tens of km that matter here.
 * Stops early once an edge closer than `stopBelowKm` is found, since that settles the question.
 */
function edgeDistanceKm(x: number, y: number, polygon: LandPolygon, stopBelowKm: number): number {
    const kx = KM_PER_DEGREE_LONGITUDE_AT_EQUATOR * Math.cos(y * Math.PI / 180);
    const ky = KM_PER_DEGREE_LATITUDE;
    let best = Infinity;

    for (const ring of polygon.rings) {
        for (let i = 0; i < ring.length - 2; i += 2) {
            const ax = (ring[i] - x) * kx;
            const ay = (ring[i + 1] - y) * ky;
            const dx = (ring[i + 2] - x) * kx - ax;
            const dy = (ring[i + 3] - y) * ky - ay;
            const length = dx * dx + dy * dy;

            // Nearest point of the edge to the origin (the queried point)
            const t = length === 0 ? 0 : Math.max(0, Math.min(1, -(ax * dx + ay * dy) / length));
            const distance = Math.hypot(ax + t * dx, ay + t * dy);

            if (distance < best) {
                best = distance;
                if (best < stopBelowKm) return best;
            }
        }
    }

    return best;
}

/**
 * Distance in km from a point on land to the sea. 0 for a point that is not on land,
 * or that is outside the area the coastline data covers.
 *
 * With `stopBelowKm` the search ends as soon as the point is known to be closer than
 * that, so the returned distance is then only an upper bound.
 */
export function distanceToCoastKm(longitude: number, latitude: number, stopBelowKm = 0): number {
    if (!Number.isFinite(longitude) || !Number.isFinite(latitude)) return 0;

    const x = wrapLongitude(longitude);
    const y = latitude;

    for (const polygon of load()) {
        if (x < polygon.west || x > polygon.east || y < polygon.south || y > polygon.north) continue;
        if (!inPolygon(x, y, polygon)) continue;

        return edgeDistanceKm(x, y, polygon, stopBelowKm);
    }

    return 0;
}

/** True when the point is on land and further than `thresholdKm` from the sea. */
export function isInland(longitude: number, latitude: number, thresholdKm: number = INLAND_KM): boolean {
    return distanceToCoastKm(longitude, latitude, thresholdKm) > thresholdKm;
}
